88	    /**
89	     * Default the registration date to the server's current date when none was
90	     * supplied, then roll the effective date forward onto a business day so a
91	     * weekend registration date always lands on the following Monday. Runs only
92	     * on insert.
93	     */
94	    @PrePersist
95	    private void defaultRegistrationDate() {
96	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
97	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
98	    }
99	
100	    public String getAddress() {
101	        return this.address;
102	    }
103	
104	    public void setAddress(String address) {
105	        this.address = address;
106	    }
107	
108	    public String getCity() {
109	        return this.city;
110	    }
111	
112	    public void setCity(String city) {
113	        this.city = city;
114	    }
115	
116	    public String getTelephone() {
117	        return this.telephone;
118	    }
119	
120	    public void setTelephone(String telephone) {
121	        this.telephone = telephone;
122	    }
123	
124	    public String getEmail() {
125	        return this.email;
126	    }
127	
128	    public void setEmail(String email) {
129	        this.email = email;
130	    }
131	
132	    public String getPostcode() {
133	        return this.postcode;
134	    }
135	
136	    public void setPostcode(String postcode) {
137	        this.postcode = postcode;
138	    }
139	
140	    public LocalDate getRegistrationDate() {
141	        return this.registrationDate;
142	    }
143	
144	    public void setRegistrationDate(LocalDate registrationDate) {
145	        this.registrationDate = registrationDate;
146	    }
147	
148	    public LocalDate getBirthDate() {
149	        return this.birthDate;
150	    }
151	
152	    public void setBirthDate(LocalDate birthDate) {
153	        this.birthDate = birthDate;
154	    }
155	
156	    public String getCustomerCode() {
157	        return this.customerCode;
158	    }
159	
160	    public void setCustomerCode(String customerCode) {
161	        this.customerCode = customerCode;
162	    }
163	
164	    public String getHouseholdId() {
165	        return this.householdId;
166	    }
167	
168	    public void setHouseholdId(String householdId) {
169	        this.householdId = householdId;
170	    }
171	
172	    public Integer getNamesakeCount() {
173	        return this.namesakeCount;
174	    }
175	
176	    public void setNamesakeCount(Integer namesakeCount) {
177	        this.namesakeCount = namesakeCount;
178	    }
179	
180	    public Integer getHouseholdSize() {
181	        return this.householdSize;
182	    }
183	
184	    public void setHouseholdSize(Integer householdSize) {
185	        this.householdSize = householdSize;
186	    }
187	
188	    public String getMembershipNumber() {
189	        return this.membershipNumber;
190	    }
191	
192	    public void setMembershipNumber(String membershipNumber) {
193	        this.membershipNumber = membershipNumber;
194	    }
195	
196	    public Integer getPossibleDuplicateOf() {
197	        return this.possibleDuplicateOf;
198	    }
199	
200	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
201	        this.possibleDuplicateOf = possibleDuplicateOf;
202	    }
203	
204	    /**
205	     * Return whether this owner is a possible duplicate: true when it was created while an existing
206	     * owner already shared its last name and postcode under a different telephone, i.e. when a
207	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
208	     */
209	    @Transient
210	    public boolean getPossibleDuplicate() {
211	        return this.possibleDuplicateOf != null;
212	    }
213	
214	    /**
215	     * Return this owner's name formatted as {@code LastName, FirstName}.
216	     */
217	    @Transient
218	    public String getDisplayName() {
219	        return this.getLastName() + ", " + this.getFirstName();
220	    }
221	
222	    /**
223	     * Return this owner's telephone formatted for human display: the country code, a space, then
224	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
225	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
226	     */
227	    @Transient
228	    public String getTelephoneDisplay() {
229	        return TelephoneFormatter.format(this.telephone);
230	    }
231	
232	    /**
233	     * Return this owner's identity key: the derived value formed as
234	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
235	     * contributes an empty segment). Members of the same household share a household id but, having
236	     * different telephones, still have distinct identity keys. The telephone and email are expected
237	     * to already be in their normalized storage form.
238	     */
239	    @Transient
240	    public String getIdentityKey() {
241	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
242	    }
243	
244	    private static String orEmpty(String value) {
245	        return value == null ? "" : value;
246	    }
247	
248	    /**
249	     * Return this owner's locality: the REGION segment of the owner's
250	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
251	     * When no customer code has been assigned yet the region is resolved directly from the
252	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
253	     */
254	    @Transient
255	    public String getLocality() {
256	        if (this.customerCode != null && !this.customerCode.isBlank()) {
257	            return CustomerCodeGenerator.regionOf(this.customerCode);
258	        }
259	        return RegionResolver.regionFor(this.postcode, this.city);
260	    }
261	
262	    /**
263	     * Return this owner's timezone: the IANA name mapped from the owner's
264	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
265	     * region has no known timezone.
266	     */
267	    @Transient
268	    public String getTimezone() {
269	        return RegionTimezones.timezoneOf(getLocality());
270	    }
271	
272	    /**
273	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
274	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
275	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
276	     * for long tenure ({@link #getTenureDays() tenure} of more than 365 days).
277	     */
278	    @Transient
279	    public int getMembershipPoints() {
280	        boolean hasEmail = this.email != null && !this.email.isEmpty();
281	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
282	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
283	        boolean longTenure = getTenureDays() > 365;
284	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
285	    }
286	
287	    /**
288	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
289	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
290	     */
291	    @Transient
292	    public int getMembershipLevel() {
293	        return MembershipPoints.levelFor(getMembershipPoints());
294	    }
295	
296	    /**
297	     * Return this owner's tenure in whole days: the number of days elapsed from the
298	     * {@link #getRegistrationDate() registration date} to today. A newly created owner
299	     * whose registration date is today has zero tenure. Zero when no registration date
300	     * is known.
301	     */
302	    @Transient
303	    public long getTenureDays() {
304	        if (this.registrationDate == null) {
305	            return 0;
306	        }
307	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
308	    }
309	
310	    /**
311	     * Return this owner's check digit: the single Luhn check digit computed over the
312	     * digits of the {@link #getCustomerCode() customer code}.
313	     */
314	    @Transient
315	    public int getCheckDigit() {
316	        return LuhnCheckDigit.of(this.customerCode);
317	    }
318	
319	    /**
320	     * Return this owner's preferred contact channel: {@code EMAIL} when an
321	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
322	     */
323	    @Transient
324	    public String getContactPreference() {
325	        boolean hasEmail = this.email != null && !this.email.isEmpty();
326	        return hasEmail ? "EMAIL" : "PHONE";
327	    }
328	
329	    /**
330	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
331	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
332	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
333	     */
334	    @Transient
335	    public String getAgeBand() {
336	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
337	        return ageBand == null ? null : ageBand.name();
338	    }
339	
340	    protected Set<Pet> getPetsInternal() {
341	        if (this.pets == null) {
342	            this.pets = new HashSet<>();
343	        }
344	        return this.pets;
345	    }
346	
347	    protected void setPetsInternal(Set<Pet> pets) {
348	        this.pets = pets;
349	    }
350	
351	    public List<Pet> getPets() {
352	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
353	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
354	        return Collections.unmodifiableList(sortedPets);
355	    }
356	
357	    public void setPets(List<Pet> pets) {
358	        this.pets = new HashSet<>(pets);
359	    }
360	
361	    public void addPet(Pet pet) {
362	        getPetsInternal().add(pet);
363	        pet.setOwner(this);
364	    }
365	
366	    /**
367	     * Return the Pet with the given name, or null if none found for this Owner.
368	     *
369	     * @param name to test
370	     * @return true if pet name is already in use
371	     */
372	    public Pet getPet(String name) {
373	        return getPet(name, false);
374	    }
375	
376	    /**
377	     * Return the Pet with the given name, or null if none found for this Owner.
378	     *
379	     * @param name to test
380	     * @return true if pet name is already in use
381	     */
382	    public Pet getPet(String name, boolean ignoreNew) {
383	        name = name.toLowerCase();
384	        for (Pet pet : getPetsInternal()) {
385	            if (!ignoreNew || !pet.isNew()) {
386	                String compName = pet.getName();
387	                compName = compName.toLowerCase();
388	                if (compName.equals(name)) {
389	                    return pet;
390	                }
391	            }
392	        }
393	        return null;
394	    }
395	
396	    public Pet getPet(Integer petId) {
397	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
398	    }
399	
400	    @Override
401	    public String toString() {
402	        return new ToStringCreator(this)
403	
404	            .append("id", this.getId())
405	            .append("new", this.isNew())
406	            .append("lastName", this.getLastName())
407	            .append("firstName", this.getFirstName())
408	            .append("address", this.address)
409	            .append("city", this.city)
410	            .append("telephone", this.telephone)
411	            .append("email", this.email)
412	            .toString();
413	    }
414	}
