19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Shared SHA-256 hashing utility. Provides the lower-case hexadecimal digest of a string's UTF-8
25	 * bytes so that every feature that fingerprints a value (household ids, customer codes) hashes it
26	 * the same way.
27	 */
28	public final class Sha256 {
29	
30	    private Sha256() {
31	    }
32	
33	    /**
34	     * Return the full lower-case hexadecimal SHA-256 digest of the UTF-8 bytes of {@code value}.
35	     *
36	     * @param value the value to hash
37	     * @return the 64-character lower-case hex digest
38	     */
39	    public static String hex(String value) {
40	        try {
41	            byte[] digest = MessageDigest.getInstance("SHA-256")
42	                .digest(value.getBytes(StandardCharsets.UTF_8));
43	            StringBuilder sb = new StringBuilder(digest.length * 2);
44	            for (byte b : digest) {
45	                sb.append(String.format("%02x", b));
46	            }
47	            return sb.toString();
48	        }
49	        catch (NoSuchAlgorithmException ex) {
50	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
51	        }
52	    }
53	}
