129	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
130	        Collection<Owner> owners;
131	        if (lastName != null) {
132	            owners = this.clinicService.findOwnerByLastName(lastName);
133	        } else {
134	            owners = this.clinicService.findAllOwners();
135	        }
136	        if (owners.isEmpty()) {
