17	package org.springframework.samples.petclinic.rest.validation;
18	
19	/**
20	 * Normalizes an owner's telephone to its canonical E.164 storage form. Spaces, dashes and
21	 * brackets (and any other formatting) are stripped. A leading {@code '+'} and its country code are
22	 * kept as given; otherwise the default country code {@code '+61'} is assumed and a single leading
23	 * {@code '0'} is dropped from the national digits. The result is {@code '+'} followed by 8 to 15
24	 * digits.
25	 *
26	 * <p>For a recognised country (see {@link E164Country}) the national number must additionally carry
27	 * exactly the number of digits that country requires ({@code +61} needs 9, {@code +1} needs 10);
28	 * otherwise the value is rejected.
29	 */
30	public final class TelephoneNormalizer {
31	
32	    private static final E164Country DEFAULT_COUNTRY = E164Country.AUSTRALIA;
33	
34	    private static final int MIN_DIGITS = 8;
35	
36	    private static final int MAX_DIGITS = 15;
37	
38	    private TelephoneNormalizer() {
39	    }
40	
41	    /**
42	     * Converts the submitted telephone to its canonical E.164 storage form.
43	     *
44	     * @param telephone the submitted telephone, possibly containing formatting characters
45	     * @return the normalized E.164 telephone: {@code '+'} followed by 8 to 15 digits
46	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
47	     *                                   national-number length is wrong for its country
48	     */
49	    public static String normalize(String telephone) {
50	        String trimmed = telephone == null ? "" : telephone.trim();
51	        boolean hasCountryCode = trimmed.startsWith("+");
52	        String digits = trimmed.replaceAll("\\D", "");
53	        E164Country country;
54	        String nationalNumber;
55	        if (hasCountryCode) {
56	            country = E164Country.forDigits(digits).orElse(null);
57	            nationalNumber = country == null ? digits : digits.substring(country.callingCode().length());
58	        } else {
59	            if (digits.startsWith("0")) {
60	                digits = digits.substring(1);
61	            }
62	            country = DEFAULT_COUNTRY;
63	            nationalNumber = digits;
64	        }
65	        String callingCode = country == null ? "" : country.callingCode();
66	        String allDigits = callingCode + nationalNumber;
67	        if (allDigits.length() < MIN_DIGITS || allDigits.length() > MAX_DIGITS) {
68	            throw new InvalidTelephoneException(
69	                "Telephone must form a valid E.164 number with " + MIN_DIGITS + " to " + MAX_DIGITS
70	                    + " digits after the '+'");
71	        }
72	        if (country != null && nationalNumber.length() != country.nationalNumberLength()) {
73	            throw new InvalidTelephoneException(
74	                "Telephone for country code '+" + callingCode + "' requires "
75	                    + country.nationalNumberLength() + " national digits, but got "
76	                    + nationalNumber.length());
77	        }
78	        return "+" + allDigits;
79	    }
80	}
