17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.regex.Pattern;
20	
21	/**
22	 * Normalizes an owner's optional email to its canonical storage form. The email is lower-cased,
23	 * and a value that is present must be a syntactically valid address.
24	 */
25	public final class EmailNormalizer {
26	
27	    private static final Pattern EMAIL_PATTERN =
28	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
29	
30	    private EmailNormalizer() {
31	    }
32	
33	    /**
34	     * Returns the canonical, lower-cased form of the submitted email. Email is optional, so a
35	     * {@code null} value is returned unchanged; any present value must be syntactically valid.
36	     *
37	     * @param email the submitted email, or {@code null} if none was provided
38	     * @return the lower-cased email, or {@code null} if none was provided
39	     * @throws InvalidEmailException if a value is present but not a syntactically valid address
40	     */
41	    public static String normalize(String email) {
42	        if (email == null) {
43	            return null;
44	        }
45	        if (!EMAIL_PATTERN.matcher(email).matches()) {
46	            throw new InvalidEmailException("Email must be a syntactically valid address");
47	        }
48	        return email.toLowerCase();
49	    }
50	}
