17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Locale;
20	
21	/**
22	 * Derives an owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the owner's
23	 * region code (derived from the postcode, see
24	 * {@link org.springframework.samples.petclinic.model.RegionResolver RegionResolver}) and HASH8 is
25	 * the first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's normalized
26	 * telephone concatenated with the last name (e.g. {@code NSW-1A2B3C4D}). The code carries no
27	 * sequence number, so it is stable for a given region and (telephone, last name) pair.
28	 */
29	public final class CustomerCodeGenerator {
30	
31	    /** Number of leading hex characters of the SHA-256 digest kept as the code's hash segment. */
32	    private static final int HASH_LENGTH = 8;
33	
34	    private static final char SEPARATOR = '-';
35	
36	    private CustomerCodeGenerator() {
37	    }
38	
39	    /**
40	     * Builds the customer code for a new owner.
41	     *
42	     * @param region              the owner's region code
43	     * @param normalizedTelephone the owner's telephone in its normalized storage form
44	     * @param lastName            the owner's last name
45	     * @return the customer code, e.g. {@code "NSW-1A2B3C4D"}
46	     */
47	    public static String generate(String region, String normalizedTelephone, String lastName) {
48	        String hash8 = Sha256.hex(orEmpty(normalizedTelephone) + orEmpty(lastName))
49	            .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
50	        return region + SEPARATOR + hash8;
51	    }
52	
53	    /**
54	     * Return the REGION segment of a customer code (the text before the separator).
55	     *
56	     * @param customerCode a customer code produced by {@link #generate}
57	     * @return the region segment
58	     */
59	    public static String regionOf(String customerCode) {
60	        int separator = customerCode.indexOf(SEPARATOR);
61	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
62	    }
63	
64	    private static String orEmpty(String value) {
65	        return value == null ? "" : value;
66	    }
67	}
