20	import java.util.stream.Collectors;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.service.ClinicService;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Ensures a newly generated {@link CustomerCodeGenerator customer code} is unique across existing
28	 * owners. When the candidate collides with an existing owner's customer code, {@code -<n>} is
29	 * appended with the smallest {@code n} of 2 or more that yields an unused code.
30	 */
31	@Component
32	public class CustomerCodeDeduplicator {
33	
34	    private static final char SEPARATOR = '-';
35	
36	    private final ClinicService clinicService;
37	
38	    public CustomerCodeDeduplicator(ClinicService clinicService) {
39	        this.clinicService = clinicService;
40	    }
41	
42	    /**
43	     * Returns the candidate customer code, or a de-duplicated variant if it collides with an
44	     * existing owner's customer code.
45	     *
46	     * @param candidate the freshly generated customer code
47	     * @return a customer code that no existing owner already holds
48	     */
49	    public String deduplicate(String candidate) {
50	        Set<String> existing = this.clinicService.findAllOwners().stream()
51	            .map(Owner::getCustomerCode)
52	            .filter(code -> code != null)
53	            .collect(Collectors.toSet());
54	        if (!existing.contains(candidate)) {
55	            return candidate;
56	        }
57	        int suffix = 2;
58	        while (existing.contains(candidate + SEPARATOR + suffix)) {
59	            suffix++;
60	        }
61	        return candidate + SEPARATOR + suffix;
62	    }
63	}
